def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import sys
    from collections import defaultdict

    # Initialize the grid with default value 0
    grid = [[0] * (N + 1) for _ in range(N + 1)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # Create a 3D DP table
    dp = [[[-sys.maxsize] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[1][1][1] = grid[1][1]

    # Fill the DP table
    for i1 in range(1, N + 1):
        for j1 in range(1, N + 1):
            for i2 in range(1, N + 1):
                j2 = i1 + j1 - i2
                if j2 < 1 or j2 > N or grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    continue
                if i1 == 1 and j1 == 1 and i2 == 1:
                    continue
                current_value = grid[i1][j1] if (i1, j1) == (i2, j2) else grid[i1][j1] + grid[i2][j2]
                dp[i1][j1][i2] = max(
                    dp[i1 - 1][j1][i2 - 1], dp[i1 - 1][j1][i2], dp[i1][j1 - 1][i2 - 1], dp[i1][j1 - 1][i2]
                ) + current_value

    return max(dp[N][N][N], 0)

def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        return f"{N}/{level - N + 1}"
    else:
        return f"{level - N + 1}/{N}"

def max_product(num_str: str, N: int, K: int) -> int:
    # Convert the string into a list of integers for easier manipulation
    nums = [int(num_str[i]) for i in range(N)]

    # Initialize a DP table where dp[i][j] represents the maximum product
    # using the first i+1 digits with j multiplication signs
    dp = [[0] * (K + 1) for _ in range(N)]

    # Fill the base case where there are no multiplication signs
    for i in range(N):
        dp[i][0] = int(num_str[:i+1])

    # Fill the DP table
    for j in range(1, K + 1):
        for i in range(j, N):
            for p in range(j-1, i):
                dp[i][j] = max(dp[i][j], dp[p][j-1] * int(num_str[p+1:i+1]))

    return dp[N-1][K]

