def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        elif terms:  # Add '+' for positive coefficients, but not for the first term
            term += '+'
        abs_coeff = abs(coeff)
        if abs_coeff != 1 or degree == 0:
            term += str(abs_coeff)
        if degree > 0:
            term += 'x'
        if degree > 1:
            term += f'^{degree}'
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last == 0:
        return 1
    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, min(last // 2 + 1, n + 1)):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
    x0 (int): The GCD that each pair (P, Q) must have.
    y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
    int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    from math import gcd

    def is_coprime(a, b):
        return gcd(a, b) == 1

    if y0 % x0 != 0:
        return 0

    target = y0 // x0
    count = 0

    for a in range(1, int(target**0.5) + 1):
        if target % a == 0:
            b = target // a
            if is_coprime(a, b):
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps > 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_string = current[:pos] + tgt + current[pos + len(src):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                start = pos + 1

    return 'NO ANSWER!'

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert the number to a string to easily access each digit
    original_str = str(n)
    digits = set("0123456789")

    # Create a dictionary to map each digit to its possible transformations
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[str(x)].add(str(y))

    # BFS to explore all possible numbers
    queue = deque([original_str])
    visited = set([original_str])

    while queue:
        current = queue.popleft()

        # Try to apply each transformation rule to each digit of the current number
        for i in range(len(current)):
            if current[i] in transform_map:
                for new_digit in transform_map[current[i]]:
                    new_number = current[:i] + new_digit + current[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, statement_list in statements.items():
        participant_is_liar = participant in liar_count
        for statement in statement_list:
            if statement in days_of_week:
                continue
            if statement == f"I am guilty.":
                if participant != scenario and not participant_is_liar:
                    return False
                elif participant == scenario and participant_is_liar:
                    return False
            elif statement.startswith(" is guilty."):
                target = statement.split()[0]
                if target == scenario and not participant_is_liar:
                    return False
                elif target == scenario and participant_is_liar:
                    continue
                elif target != scenario and participant_is_liar:
                    continue
                elif target != scenario and not participant_is_liar:
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    player_score = 0
    opponent_score = 0
    game_scores = []

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If there is a game in progress, add its current score
    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    cleared = [False] * (l + 1)
    for start, end in areas:
        for i in range(start, end + 1):
            cleared[i] = True
    return sum(1 for tree in cleared if not tree)

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, a[i - 1] + 1):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD
                else:
                    break

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))
        elif c.isupper():
            return chr((ord(c) - ord(k) + 26) % 26 + ord('A'))
        else:
            return c

    key = key.lower()
    key_length = len(key)
    decrypted = []

    for i, c in enumerate(ciphertext):
        k = key[i % key_length]
        decrypted.append(shift_char(c, k))

    return ''.join(decrypted)

